-- Backpacks: models worn on the back through a hidden aura. The spells' visuals and the models
-- are in the realm's client patch (built with buildthehomelab/wow-mod-visible-bags tools).
CREATE TABLE IF NOT EXISTS `mod_transmog_plus_backpacks` (
    `Id` int(10) unsigned NOT NULL,
    `Name` varchar(64) NOT NULL,
    `SpellId` int(10) unsigned NOT NULL,
    `UnlockPhase` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'individual progression phase cleared (quest 66000+n); 0 = not by phase',
    `UnlockItem` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'item that unlocks it on use; 0 = none',
    `Model` varchar(128) NOT NULL DEFAULT '' COMMENT 'client model path, for the addon preview',
    `SortOrder` int(10) unsigned NOT NULL DEFAULT 0,
    PRIMARY KEY (`Id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `mod_transmog_plus_backpacks`;
INSERT INTO `mod_transmog_plus_backpacks` (`Id`, `Name`, `SpellId`, `UnlockPhase`, `UnlockItem`, `Model`, `SortOrder`) VALUES
